/* Public, generic wellness PWA. All personal content is imported on-device. No network API or trackers. */
(()=>{'use strict';
const VER=4, WEEK=['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'], SHORT=['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];
const TABS=[['today','Today','☀'],['food','Food','♨'],['fitness','Fitness','✦'],['health','Health','♡'],['progress','Progress','▥'],['chat','Chat','◉'],['settings','Settings','⚙']];
const QUOTES=['A flexible plan is still a plan.','Care for yourself in ways that work for your real life.','Progress also includes rest.','Small, practical steps add up.','You are allowed to have a gentler day.'];
const EMPTY=()=>({schema:VER,profile:{name:'',timezone:'Asia/Kolkata',weightStart:'',weightGoal:'',weightLong:'',meditationMinutes:15,notes:''},config:{tasks:[],workouts:[],care:{morning:[],night:[],body:[]},products:[],mealIdeas:{Breakfast:[],Lunch:[],Dinner:[],Snack:[]},symptomFields:[],healthMetrics:[]},days:{},meals:[],workouts:[],sessions:[],episodes:[],checkins:[],metrics:[],meditations:[],chat:[],workoutOverrides:{},extra:{createdAt:new Date().toISOString()}});
let data=EMPTY(),db=null,writeChain=Promise.resolve(),tab='today',selected='',modal=null,carePeriod='morning',healthView='wellness',pending=null,medTimer=null,chatDraft='',initialized=false,storageWarning='',homeCheckPeriod='morning',fitnessWeekShift=0;
const $=id=>document.getElementById(id);
const safe=s=>String(s??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
const txt=s=>safe(s).replaceAll('\n','<br>');
const uid=()=>globalThis.crypto?.randomUUID?.()||('x'+Date.now()+Math.random().toString(36).slice(2));
const isoDay=(d=new Date())=>{let p=new Intl.DateTimeFormat('en-US',{timeZone:'Asia/Kolkata',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(d);let o=Object.fromEntries(p.map(x=>[x.type,x.value]));return `${o.year}-${o.month}-${o.day}`};
const atDay=s=>new Date(`${s}T12:00:00Z`);
const dow=s=>atDay(s).getUTCDay();
const plus=(s,n)=>{let d=atDay(s);d.setUTCDate(d.getUTCDate()+n);return d.toISOString().slice(0,10)};
const monday=s=>plus(s,-((dow(s)+6)%7));
const dateLabel=s=>atDay(s).toLocaleDateString('en-IN',{timeZone:'UTC',weekday:'short',day:'numeric',month:'short'});
const timeLabel=s=>!s?'Any time':new Date(`2020-01-01T${s}:00`).toLocaleTimeString('en-IN',{hour:'numeric',minute:'2-digit'});
const fmtDateTime=s=>s?new Date(s).toLocaleString('en-IN',{timeZone:'Asia/Kolkata',dateStyle:'medium',timeStyle:'short'}):'Not recorded';
const n=v=>v===''?null:(Number.isFinite(Number(v))?Number(v):null);
function toast(s){let el=$('toast');if(!el)return;el.textContent=s;el.classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>el.classList.remove('show'),2900)}
function day(s){return data.days[s]||(data.days[s]={tasks:{},water:0})}
function getTask(s,id){return data.days[s]?.tasks?.[id]||''}
function save(){const snapshot=structuredClone(data);if(db){writeChain=writeChain.then(()=>new Promise((resolve,reject)=>{let tx=db.transaction('records','readwrite');tx.objectStore('records').put(snapshot,'main');tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)})).catch(e=>{console.error(e);storageWarning='Unable to save locally. Please export a backup.';toast('Save failed — export a backup')});}else{try{localStorage.setItem('wellness-companion-generic-v4',JSON.stringify(snapshot))}catch(e){storageWarning='Unable to save locally. Export your data.';toast('Save failed')}}}
function openDb(){return new Promise((resolve,reject)=>{const req=indexedDB.open('wellness-companion-generic-v4',1);req.onupgradeneeded=()=>req.result.createObjectStore('records');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)})}
function loadDb(){return new Promise((resolve,reject)=>{const tx=db.transaction('records','readonly');let r=tx.objectStore('records').get('main');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
function normalise(raw){let d=EMPTY();if(!raw||typeof raw!=='object')throw new Error('Not a valid app file');if(raw.kind==='companion-private-setup'){if(!raw.profile||!raw.config||!Array.isArray(raw.config.tasks))throw new Error('Private setup file is incomplete');d.profile={...d.profile,...raw.profile};d.config={...d.config,...raw.config};}else if(raw.kind==='companion-backup'&&raw.state?.config?.tasks){d={...d,...raw.state};d.profile={...EMPTY().profile,...d.profile};d.config={...EMPTY().config,...d.config};}else throw new Error('Choose a Companion private setup or backup JSON');
for(const key of ['tasks','workouts','products','symptomFields','healthMetrics'])if(!Array.isArray(d.config[key]))d.config[key]=[];
if(!d.config.care||typeof d.config.care!=='object')d.config.care={morning:[],night:[],body:[]};
if(!d.config.mealIdeas||typeof d.config.mealIdeas!=='object')d.config.mealIdeas={Breakfast:[],Lunch:[],Dinner:[],Snack:[]};
for(const key of ['meals','workouts','sessions','episodes','checkins','metrics','meditations','chat'])if(!Array.isArray(d[key]))d[key]=[];
if(!d.days||typeof d.days!=='object')d.days={};if(!d.workoutOverrides||typeof d.workoutOverrides!=='object')d.workoutOverrides={};d.schema=VER;return d}
function saveFile(name,value,type='application/json'){const blob=new Blob([typeof value==='string'?value:JSON.stringify(value,null,2)],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),3000)}
function backup(){saveFile('companion-private-backup-'+isoDay()+'.json',{kind:'companion-backup',version:VER,exportedAt:new Date().toISOString(),state:data});toast('Private backup saved to Files / Downloads')}
function csvCell(v){return '"'+String(v??'').replaceAll('"','""')+'"'}
function csv(name,headers,rows){saveFile(name,[headers,...rows].map(row=>row.map(csvCell).join(',')).join('\r\n'),'text/csv;charset=utf-8')}
function sessionDate(m){return m.date||isoDay(new Date(m.start||Date.now()))}
function workout(date){if(Object.hasOwn(data.workoutOverrides,date))return data.workoutOverrides[date];return data.config.workouts.find(x=>Number(x.day)===dow(date))?.name||''}
function workoutTime(date){return data.config.workouts.find(x=>Number(x.day)===dow(date))?.time||''}
function taskList(date){const d=dow(date);let tasks=data.config.tasks.filter(x=>x.active!==false&&(!Array.isArray(x.days)||x.days.includes(d))&&(!x.endDate||x.endDate>=date)&&(!x.startDate||x.startDate<=date)).map(x=>({...x}));let w=workout(date);if(w)tasks.push({id:'workout-of-day',name:'Workout · '+w,time:workoutTime(date),group:'Fitness',category:'workout',notes:'Your weekly workout can be moved in Fitness'});return tasks.sort((a,b)=>(a.time||'99:99').localeCompare(b.time||'99:99'))}
function syncMealChecklist(date,type){const matches=taskList(date).filter(t=>t.name.toLowerCase().includes(type.toLowerCase())&&/log|record actual/i.test(t.name));if(!matches.length)return;const today=day(date),auto=today.autoMealTasks||(today.autoMealTasks={});const logged=data.meals.some(m=>m.date===date&&m.type===type);for(const t of matches){if(logged){if(!getTask(date,t.id)||auto[t.id]){today.tasks[t.id]='done';auto[t.id]=true}}else if(auto[t.id]){delete today.tasks[t.id];delete auto[t.id]}}}
function setStatus(date,id,status){const task=taskList(date).find(t=>t.id===id);if(status==='done'&&task?.category==='medication'&&!confirm('Confirm you actually took this dose?'))return;day(date).tasks[id]=status;if(day(date).autoMealTasks)delete day(date).autoMealTasks[id];save();render();toast(status==='done'?'Marked complete':status==='skipped'?'Marked skipped':'Entry cleared')}
function completion(date){const arr=taskList(date);let done=arr.filter(t=>getTask(date,t.id)==='done').length;return {done,total:arr.length,pct:arr.length?Math.round(done/arr.length*100):0}}
function latestMetric(kind){return data.metrics.filter(x=>x.kind===kind).sort((a,b)=>(b.date+b.time).localeCompare(a.date+a.time))[0]}
function addMeasure(kind,val,date=isoDay(),time=''){let num=n(val);if(num===null)throw Error('Enter a number');data.metrics.push({id:uid(),kind,value:num,date,time});save();render();toast('Measurement saved')}
function section(title,content,subtitle=''){return `<section class="card section"><div class="card-head"><div><h3 class="card-title">${safe(title)}</h3>${subtitle?`<div class="card-caption">${safe(subtitle)}</div>`:''}</div></div>${content}</section>`}
const btn=(label,act,extra='',cls='btn btn-sm')=>`<button class="${cls}" data-action="${act}" ${extra}>${label}</button>`;
const field=(label,name,type='text',value='',extra='')=>`<label class="field">${safe(label)}<input name="${safe(name)}" type="${safe(type)}" value="${safe(value)}" ${extra}></label>`;
const textarea=(label,name,value='',placeholder='')=>`<label class="field">${safe(label)}<textarea name="${safe(name)}" placeholder="${safe(placeholder)}">${safe(value)}</textarea></label>`;
const dropdown=(label,name,choices,value='')=>`<label class="field">${safe(label)}<select name="${safe(name)}">${choices.map(x=>{let a=Array.isArray(x)?x:[x,x];return `<option value="${safe(a[0])}" ${String(a[0])===String(value)?'selected':''}>${safe(a[1])}</option>`}).join('')}</select></label>`;
function title(){return TABS.find(t=>t[0]===tab)?.[1]||'Today'}
function shell(content){const first=(data.profile.name||'').trim().split(' ')[0]||'there';return `<div class="shell"><aside class="sidebar"><div class="brand"><div class="brand-mark">✳</div><div class="brand-text">My Wellness<br>Companion<span class="brand-small">YOUR CALMER DAY</span></div></div><nav class="side-nav">${TABS.map(([key,label,sym])=>`<button class="nav-item ${tab===key?'active':''}" data-action="tab" data-value="${key}"><span aria-hidden="true">${sym}</span>${label}</button>`).join('')}</nav><div class="side-bottom"><div class="private-note">Your personal records stay on this device. Back up regularly.</div><div class="side-footer">Independent · offline-first</div></div></aside><main class="main"><div class="topbar"><div class="eyebrow">PERSONAL WELLBEING • YOUR SPACE</div><div class="top-actions">${btn('⚙','tab','data-value="settings"','icon-btn')}<div class="avatar">${safe(first[0].toUpperCase())}</div></div></div>${storageWarning?`<div class="banner-alert">${safe(storageWarning)}</div>`:''}${content}</main><nav class="bottom-nav">${TABS.filter(x=>x[0]!=='settings').map(([key,label,sym])=>`<button data-action="tab" data-value="${key}" class="${tab===key?'active':''}"><span style="font-size:20px">${sym}</span>${label}</button>`).join('')}</nav>${tab!=='chat'?`<button class="floating-chat" aria-label="Ask companion" data-action="tab" data-value="chat">◉</button>`:''}</div>${modal||''}`}
function render(){if(!initialized)return;let content=tab==='today'?todayPage():tab==='food'?foodPage():tab==='fitness'?fitnessPage():tab==='health'?healthPage():tab==='progress'?progressPage():tab==='chat'?chatPage():settingsPage();$('app').innerHTML=shell(content);document.documentElement.classList.toggle('dark',localStorage.getItem('companion-theme')==='dark');if(tab==='chat'){let list=$('chatMessages');if(list)list.scrollTop=list.scrollHeight}}
function dateStrip(){return `<div class="date-strip">${btn('←','date-shift','data-dir="-1"')}<label class="field"><input type="date" id="daySelect" value="${safe(selected)}" aria-label="Selected day"></label>${btn('→','date-shift','data-dir="1"')}</div>`}
function taskRows(items,date){if(!items.length)return `<div class="empty">Nothing scheduled here yet. Add a task in Settings.</div>`;return `<div class="task-list">${items.map(t=>{const status=getTask(date,t.id);return `<div class="task"><button class="check ${status==='done'?'done':status==='skipped'?'skipped':''}" aria-label="${status==='done'?'Unmark':'Complete'} ${safe(t.name)}" data-action="task-toggle" data-id="${safe(t.id)}" data-day="${date}">${status==='done'?'✓':status==='skipped'?'–':''}</button><div class="task-info"><div class="task-name ${status==='done'?'complete':''}">${safe(displayTaskName(t))}</div><div class="task-desc">${safe(t.notes||t.category||'')}</div></div><span class="task-time">${safe(timeLabel(t.time))}</span>${btn('⋯','task-menu',`data-id="${safe(t.id)}" data-day="${date}"`,'more-btn')}</div>`}).join('')}</div>`}
function displayTaskName(t){return String(t.name||'').replace(/^(Morning|Afternoon|Evening|Night)\s*[·:—–-]\s*/i,'').trim()}
function dayPeriods(date){const arr=taskList(date);const period=x=>['Morning','Afternoon','Evening','Night'].includes(x.group)?x.group:x.category==='workout'?'Morning':'Afternoon';return ['Morning','Afternoon','Evening','Night'].map(g=>({name:g,items:arr.filter(x=>period(x)===g)}))}
function grouped(date){return dayPeriods(date).map(({name,items})=>`<div class="routine-block"><div class="routine-block-title">${name} <span>${items.filter(t=>getTask(date,t.id)==='done').length}/${items.length}</span></div>${taskRows(items,date)}</div>`).join('')}
function inlineCheckin(){let x=data.checkins.find(z=>z.date===selected&&z.period===homeCheckPeriod);return section('One-minute wellness check-in',`<div class="seg-buttons checkin-toggle"><button data-action="checkin-period" data-value="morning" class="${homeCheckPeriod==='morning'?'selected':''}">Morning</button><button data-action="checkin-period" data-value="evening" class="${homeCheckPeriod==='evening'?'selected':''}">Evening</button></div><form id="quickCheckin" class="quick-check-form"><input type="hidden" name="date" value="${selected}"><input type="hidden" name="period" value="${homeCheckPeriod}"><div class="quick-check-grid">${['energy','sleep','mood','stress'].map(k=>dropdown(k[0].toUpperCase()+k.slice(1),k,Array.from({length:5},(_,i)=>[String(i+1),`${i+1} / 5`]),x?.[k]||'3')).join('')}</div>${textarea('Anything you would like to note? (optional)','notes',x?.notes||'')}<div class="row between"><span class="card-caption">${x?'Previously saved — you can update it':'Less than a minute, and every field is optional'}</span><button type="submit" class="btn primary">${x?'Update check-in':'Save check-in'}</button></div></form>`,'Here on your home screen, whenever you need it')}
function todayPage(){let p=completion(selected),logs=data.meals.filter(x=>x.date===selected),check=data.checkins.find(x=>x.date===selected&&x.period==='morning'),scheduled=taskList(selected),quote=QUOTES[Math.floor(atDay(selected).getTime()/86400000)%QUOTES.length];return `<h1 class="page-title">Hello, ${safe((data.profile.name||'friend').split(' ')[0])}.</h1><p class="subtitle">${safe(dateLabel(selected))} · Your routines, all in one place.</p><div class="hero"><div class="hero-copy"><div class="small-label">A LITTLE ENCOURAGEMENT</div><h2>${safe(quote)}</h2><p>Every small step counts, and your plans can flex with your day.</p>${btn('Ask your companion','tab','data-value="chat"','hero-btn')}</div></div><div class="stats"><div class="stat"><div class="stat-top">Checklist ✳</div><strong>${p.done}/${p.total}</strong><small>Completed today</small></div><div class="stat"><div class="stat-top">Hydration ◉</div><strong>${data.days[selected]?.water||0}</strong><small>Glasses logged</small></div><div class="stat"><div class="stat-top">Meals ♨</div><strong>${logs.length}</strong><small>Actually recorded</small></div><div class="stat"><div class="stat-top">Energy ♡</div><strong>${check?.energy||'—'}</strong><small>Morning check-in / 5</small></div></div>${dateStrip()}${inlineCheckin()}<div class="main-grid"><div>${section('Your daily checklist',`<div class="progress-line" style="margin-bottom:14px"><i style="width:${p.pct}%"></i></div><div class="period-grid">${dayPeriods(selected).map(({name,items})=>`<section class="period-card"><div class="period-head"><span class="period-icon">${({Morning:'☀',Afternoon:'❀',Evening:'☾',Night:'✧'})[name]}</span><div><h4>${name}</h4><small>${items.filter(t=>getTask(selected,t.id)==='done').length} of ${items.length} completed</small></div></div>${taskRows(items,selected)}</section>`).join('')}</div>`,`${p.pct}% of scheduled items recorded complete`)}${section('Meals & movement · one place to log',`<p class="card-caption">Record meals with today's suggestions and activity with your weekly plan. Your diary entries appear everywhere automatically.</p><div class="actions mt">${btn('Open meal cards','tab','data-value="food"','btn primary')}${btn('Open gym & badminton','tab','data-value="fitness"')}${btn('Record a symptom','episode-open')}</div>`)}</div><div>${section('Water tracker',`<div class="row between"><span class="big-stat">${data.days[selected]?.water||0}</span><div class="actions">${btn('−','water','data-inc="-1"')}${btn('＋ One glass','water','data-inc="1"')}</div></div><p class="card-caption">A glass is a simple unit; no compulsory target.</p>`)}${section('Coming up',`<div class="stack">${scheduled.filter(t=>getTask(selected,t.id)!=='done').slice(0,6).map(t=>`<div class="mini-card"><div><div class="mini-title">${safe(displayTaskName(t))}</div><p class="mini-sub">${safe(timeLabel(t.time))} · Not yet recorded</p></div></div>`).join('')||'<p class="muted-line">Nothing pending on your checklist.</p>'}</div>`)}${section('My records stay on my phone','<div class="privacy-box">Your daily entries stay on this device. Save a private backup regularly under Settings.</div>')}</div></div>`}
function mealIdeasFor(type,date){const list=data.config.mealIdeas[type]||[];if(!list.length)return [];const dayCode=Math.floor(atDay(date).getTime()/86400000);const offset=((dayCode+['Breakfast','Lunch','Dinner','Snack'].indexOf(type)*3)%list.length+list.length)%list.length;return Array.from({length:Math.min(3,list.length)},(_,i)=>list[(offset+i)%list.length])}
function foodPage(){const logs=data.meals.filter(x=>x.date===selected).sort((a,b)=>(a.time||'').localeCompare(b.time||''));return `<h1 class="page-title">Your food, simply</h1><p class="subtitle">Meal ideas and what you actually ate, together in one card. Suggestions change each day and never count as eaten until saved.</p>${dateStrip()}<div class="meal-board">${['Breakfast','Lunch','Dinner','Snack'].map(type=>{let entries=logs.filter(x=>x.type===type),ideas=mealIdeasFor(type,selected);return `<section class="card meal-card"><div class="meal-card-header"><div><span class="meal-kicker">${({Breakfast:'GOOD MORNING',Lunch:'MIDDAY FUEL',Dinner:'WIND DOWN',Snack:'LITTLE BREAK'})[type]}</span><h3>${type}</h3></div><span class="meal-count">${entries.length?entries.length+' logged':'Not yet logged'}</span></div><div class="meal-inspo"><div class="small-label">TODAY'S IDEAS</div>${ideas.length?`<div class="meal-options">${ideas.map(v=>{let name=typeof v==='string'?v:v.name;return `<button class="meal-suggestion" type="button" data-action="meal-idea" data-meal="${safe(type)}" data-name="${safe(name)}">${safe(name)} <span>＋</span></button>`}).join('')}</div>`:'<p class="card-caption">Add suggestions to your private configuration when you like.</p>'}</div><form class="inline-meal-form" id="mealQuick-${type}"><input type="hidden" name="date" value="${selected}"><input type="hidden" name="type" value="${type}"><label class="field">What did you actually eat?<input name="name" type="text" placeholder="Write what you ate or tap an idea" maxlength="160" required></label><div class="meal-input-row">${field('Portion (optional)','portion','text','','placeholder="e.g. 2 idlis"')}${field('Time (optional)','time','time','') }</div><button type="submit" class="btn primary meal-save-btn">Save ${type.toLowerCase()}</button></form><div class="meal-logged"><div class="small-label">YOUR ACTUAL ENTRIES</div>${entries.length?entries.map(m=>`<div class="logged-entry"><div><strong>${safe(m.name)}</strong><span>${safe(m.portion||'')}${m.time?' · '+timeLabel(m.time):''}</span></div>${btn('Edit','meal-open',`data-id="${safe(m.id)}"`)}${btn('×','delete',`data-type="meals" data-id="${safe(m.id)}"`,'icon-btn')}</div>`).join(''):'<p class="card-caption">Nothing recorded here yet.</p>'}</div></section>`}).join('')}</div>${section('Your meal diary',`<p class="card-caption">All meals you save above form your diary automatically. No second login required.</p><div class="actions">${btn('Download meal history','export-meals')}${btn('Open Swiggy separately ↗','delivery-link')}</div>`)}`}
function badmintonTask(date){return taskList(date).find(t=>/badminton/i.test(t.name))}
function fitnessPage(){let weekStart=plus(monday(isoDay()),fitnessWeekShift*7);let days=Array.from({length:7},(_,i)=>plus(weekStart,i));let count=data.workouts.filter(x=>x.date>=weekStart&&x.date<=plus(weekStart,6)).length;return `<h1 class="page-title">Your movement week</h1><p class="subtitle">Gym, badminton and activity entries together. Swap your workout days without changing your original plan.</p><div class="row between week-navigation"><div class="actions">${btn('← Previous week','fitness-week','data-shift="-1"')}${btn('This week','fitness-week','data-shift="0"')}${btn('Next week →','fitness-week','data-shift="1"')}</div><span class="week-pill">${fitnessWeekShift===0?'This week':fitnessWeekShift>0?'Future week':'Previous week'}</span></div>${section('Gym & badminton by weekday',`<div class="fitness-week-list">${days.map((d,i)=>{let gym=workout(d),bad=badmintonTask(d),sessions=data.workouts.filter(w=>w.date===d);return `<div class="weekday-card"><div class="weekday-head"><div class="weekday-name"><span class="weekday-bubble">${SHORT[(i+1)%7].slice(0,1)}</span><strong>${WEEK[(i+1)%7]}</strong></div>${btn('Swap gym','swap-open',`data-date="${d}"`,'btn btn-sm swap-button')}</div><div class="weekday-activity"><span class="activity-symbol">✦</span><div><strong>${safe(gym||'Gym rest day')}</strong><span>${gym?safe(timeLabel(workoutTime(d))):'No gym scheduled'}</span></div>${gym?btn('Log','session-open',`data-date="${d}" data-name="${safe(gym)}"`):''}</div>${bad?`<div class="weekday-activity badminton"><span class="activity-symbol">◉</span><div><strong>Badminton</strong><span>${bad.time?timeLabel(bad.time):'Time not set'} · ${getTask(d,bad.id)==='done'?'Marked complete':'Scheduled'}</span></div>${btn(getTask(d,bad.id)==='done'?'✓ Done':'Mark done','task-toggle',`data-id="${safe(bad.id)}" data-day="${d}"`)}${btn('Log','session-open',`data-date="${d}" data-name="Badminton"`)}</div>`:''}${taskList(d).filter(t=>/music class/i.test(t.name)).map(t=>`<div class="weekday-activity music"><span class="activity-symbol">♫</span><div><strong>Music class</strong><span>${safe(timeLabel(t.time))}</span></div></div>`).join('')}${sessions.length?`<div class="day-sessions">${sessions.map(w=>`<div class="logged-entry"><div><strong>✓ ${safe(w.name)}</strong><span>${safe(w.duration||'—')} min${w.notes?' · '+safe(w.notes):''}</span></div>${btn('Delete','delete',`data-type="workouts" data-id="${safe(w.id)}"`)}</div>`).join('')}</div>`:''}</div>`}).join('')}</div><div class="actions mt">${btn('Restore this week','week-reset')}${btn('＋ Log other activity','session-open','','btn primary')}</div>`,'Weekdays only · edits apply to this week')}${section('Activity history',`<p class="card-caption">${count} logged session${count===1?'':'s'} in this week. All workouts and badminton logs are recorded here—no separate exercise diary.</p><div class="results-list">${data.workouts.slice().sort((a,b)=>b.date.localeCompare(a.date)).slice(0,8).map(w=>`<div class="list-card"><h4>${safe(w.name)}</h4><p>${safe(dateLabel(w.date))} · ${safe(w.duration||'—')} min</p></div>`).join('')||'<div class="empty">No exercise recorded yet.</div>'}</div>`)}`}
function healthPage(){const choices=[['wellness','Check-ins'],['care','Care'],['symptoms','Symptoms'],['meditation','Meditation'],['meds','Medicines']];let head=`<h1 class="page-title">Your health, in your hands</h1><p class="subtitle">Record how you feel. This app cannot diagnose or replace professional care.</p><div class="seg-buttons mb">${choices.map(([v,t])=>`<button data-action="health-sub" data-value="${v}" class="${healthView===v?'selected':''}">${t}</button>`).join('')}</div>`;if(healthView==='wellness'){let logs=data.checkins.filter(x=>x.date===selected);return head+dateStrip()+section('One-minute check-in',`<div class="actions">${btn('Morning','checkin-open','data-period="morning"','btn primary')}${btn('Evening','checkin-open','data-period="evening"')}</div><div class="results-list mt">${logs.map(x=>`<div class="list-card"><h4>${safe(x.period)} check-in</h4><p>Energy ${safe(x.energy)}/5 · Sleep ${safe(x.sleep)}/5 · Mood ${safe(x.mood)}/5 · Stress ${safe(x.stress)}/5</p><p>${safe(x.notes)}</p></div>`).join('')||'<p class="muted-line">No check-ins recorded for this date.</p>'}</div>`)+section('Measurements',`<div class="actions">${btn('＋ Add measurement','metric-open')}</div><p class="card-caption">Track weight, blood pressure, sleep and lab results. Select the measurement unit when saving.</p>`);
}if(healthView==='care'){let items=data.config.care[carePeriod]||[];return head+`<div class="seg-buttons mb">${['morning','night','body'].map(k=>`<button data-action="care-sub" data-value="${k}" class="${carePeriod===k?'selected':''}">${k==='night'?'Night':k[0].toUpperCase()+k.slice(1)}</button>`).join('')}</div>`+section(`${carePeriod[0].toUpperCase()+carePeriod.slice(1)} routine`,items.length?`<div class="task-list">${items.map((c,i)=>`<div class="routine-step"><span class="step-no">${i+1}</span><div class="step-text"><strong>${safe(c.name)}</strong><span>${safe(c.note||'')}</span></div><button class="check ${getTask(selected,'care-'+carePeriod+'-'+i)==='done'?'done':''}" data-action="care-check" data-period="${carePeriod}" data-index="${i}" aria-label="Mark care step complete">${getTask(selected,'care-'+carePeriod+'-'+i)==='done'?'✓':''}</button></div>`).join('')}</div>`:'<div class="empty">This routine will appear after you import a private setup.</div>')+section('Your products',data.config.products.length?`<div class="results-list">${data.config.products.map(p=>`<div class="list-card"><h4>${safe(typeof p==='string'?p:p.name)}</h4><p>${safe(typeof p==='string'?'':p.note)}</p></div>`).join('')}</div>`:'<p class="muted-line">No products configured.</p>')}
if(healthView==='symptoms'){let items=data.episodes.slice().sort((a,b)=>b.start.localeCompare(a.start));let active=items.find(e=>!e.end);return head+`<div class="banner-alert section">Sudden new weakness, speech problems, vision changes, or other unusual persistent neurological symptoms may require urgent emergency assessment. This app cannot determine their cause.</div>${section('Symptom timeline',`<div class="actions">${active?btn('■ End current episode','episode-end','','btn primary'):btn('● Start episode','episode-start','','btn primary')}${btn('＋ Add / edit details','episode-open')}${btn('Export doctor CSV','episode-export')}</div><div class="results-list mt">${items.slice(0,20).map(e=>`<div class="list-card"><h4>${safe(fmtDateTime(e.start))}${!e.end?' · In progress':''}</h4><p>${safe(e.symptoms||'No description')}${e.triggers?' · Possible triggers: '+safe(e.triggers):''}</p><div class="actions">${btn('Edit','episode-open',`data-id="${safe(e.id)}"`)}${btn('Delete','delete',`data-type="episodes" data-id="${safe(e.id)}"`)}</div></div>`).join('')||'<p class="muted-line">No episodes recorded.</p>'}</div>`,'Record facts, not diagnoses.')}`}
if(healthView==='meditation'){const secsLeft=medTimer?Math.max(0,medTimer.finish-Date.now())/1000:null;const target=Number(data.profile.meditationMinutes)||15;return head+section('A little quiet',`<div class="timer-ring"><div><strong id="meditationClock">${secsLeft!==null?clock(secsLeft):`${target}:00`}</strong><span>Minutes of calm</span></div></div><div class="actions" style="justify-content:center">${medTimer?btn('Stop','meditation-stop','','btn danger'):btn('Start meditation','meditation-start','','btn primary')}${btn('Mark completed','meditation-log')}</div><p class="card-caption" style="text-align:center">The timer only runs while the page is open. You can mark a session manually if the phone locks.</p>`)+section('Meditation history',`<p class="muted-line">${data.meditations.length} sessions logged.</p>`)}
return head+section('Medication and supplements',`<div class="banner-alert">A blank log does not mean a dose was missed. Mark medicines complete only after actually taking them. This is a tracker, not prescription advice.</div><div class="task-list">${taskList(selected).filter(t=>t.category==='medication'||t.category==='supplement').map(t=>`<div class="task"><button class="check ${getTask(selected,t.id)==='done'?'done':''}" data-action="task-toggle" data-id="${safe(t.id)}" data-day="${selected}">${getTask(selected,t.id)==='done'?'✓':''}</button><div class="task-info"><div class="task-name">${safe(displayTaskName(t))}</div><div class="task-desc">${safe(t.notes||'')}</div></div><span class="task-time">${timeLabel(t.time)}</span></div>`).join('')||'<div class="empty">Import your personal medicines, or add your own in Settings.</div>'}</div>`)+section('Edit schedules',`${btn('Manage medicine reminders','tab','data-value="settings"')}`)}
function clock(s){let sec=Math.ceil(s),m=Math.floor(sec/60);return `${String(m).padStart(2,'0')}:${String(sec%60).padStart(2,'0')}`}
function progressPage(){let days=Array.from({length:14},(_,i)=>plus(isoDay(),i-13));let weights=data.metrics.filter(x=>/weight/i.test(x.kind)).sort((a,b)=>a.date.localeCompare(b.date));let last=weights.at(-1);return `<h1 class="page-title">Your progress</h1><p class="subtitle">Trends are useful; perfection isn't required.</p><div class="stats"><div class="stat"><div class="stat-top">Latest weight</div><strong>${last?safe(last.value)+' '+safe(metricUnit(last.kind,last.unit)):'—'}</strong><small>As recorded</small></div><div class="stat"><div class="stat-top">First goal</div><strong>${safe(data.profile.weightGoal||'—')}</strong><small>Editable</small></div><div class="stat"><div class="stat-top">Meal entries</div><strong>${data.meals.length}</strong><small>All time</small></div><div class="stat"><div class="stat-top">Check-ins</div><strong>${data.checkins.length}</strong><small>All time</small></div></div>${section('Last 14 days · checklist completion',`<div class="mini-chart">${days.map(d=>{let x=completion(d);return `<div title="${safe(d)}: ${x.pct}%" style="height:${Math.max(3,x.pct)}%"></div>`}).join('')}</div><div class="row between"><small>Two weeks ago</small><small>Today</small></div>`)}${section('Weight log',`<div class="actions mb">${btn('＋ Record weight','metric-open','data-kind="Weight"','btn primary')}</div><div class="results-list">${weights.slice(-12).reverse().map(m=>`<div class="list-card"><div class="row between"><strong>${safe(m.value)} ${safe(metricUnit(m.kind,m.unit))}</strong><span class="card-caption">${dateLabel(m.date)}</span></div></div>`).join('')||'<p class="muted-line">No weight entries yet.</p>'}</div>`)}${section('Weekly wellbeing reflection',`<p class="muted-line">Logged exercise: ${data.workouts.length} · Symptoms: ${data.episodes.length} · Meditation sessions: ${data.meditations.length}</p><p class="card-caption">Patterns in personal records are not a medical diagnosis.</p>`)} `}
function chatPage(){const messages=data.chat.slice(-100);return `<h1 class="page-title">Ask My Companion</h1><p class="subtitle">A private local helper for your schedules, meal records and routines. Not a generative AI service.</p><div class="chat-shell"><div class="chat-head"><div><strong>✳ Your companion</strong><div class="card-caption">Offline command assistant · No data sent to a chatbot server</div></div>${btn('Clear','chat-clear')}</div><div class="chat-list" id="chatMessages">${messages.length?messages.map(m=>`<div class="bubble ${m.role}">${txt(m.text)}</div>`).join(''):'<div class="bubble assistant">Hello! Ask me what is left today, request a workout swap, or tell me what you ate. I can use the information you have saved in this app.</div>'}${pending?`<div class="chat-response-action">${btn('Confirm change','chat-confirm','','btn primary')}${btn('Cancel','chat-cancel')}</div>`:''}</div><div class="chat-prompts">${['What is left today?','Suggest breakfast','Show my medicines','How has my progress been?','Start meditation'].map(q=>`<button data-action="chat-prompt" data-text="${safe(q)}">${safe(q)}</button>`).join('')}</div><form class="chat-compose" id="chatForm"><input type="text" name="message" maxlength="500" placeholder="Ask about today, meals or workouts…" value="${safe(chatDraft)}" aria-label="Chat message" required autocomplete="off"><button type="submit">Send</button></form></div>`}
function settingsPage(){let profile=data.profile,tasks=data.config.tasks;return `<h1 class="page-title">Your settings</h1><p class="subtitle">Everything is editable. Your private setup stays on this device.</p>${section('Privacy and backups',`<div class="privacy-box"><strong>Device-only records.</strong> This static app does not upload health information to GitHub. Anyone with access to this browser profile may be able to read local records. Export a private backup before clearing website data.</div><div class="actions mt">${btn('Download private backup','backup','','btn primary')}${btn('Import setup / backup','import')}${btn('Clear all device data','reset-open','','btn danger')}</div><div class="card-caption mt">Never upload a private setup file or backup to your public GitHub repository.</div>`)}${section('Personal profile',`<div class="actions">${btn('Edit profile and goals','profile-open','','btn primary')}${btn('Change theme','theme-toggle')}</div><div class="muted-line mt">Name: ${safe(profile.name||'Not set')} · Primary goal: ${safe(profile.weightGoal||'Not set')} · Meditation: ${safe(profile.meditationMinutes)} minutes</div>`)}${section('Scheduled checklist items',`<div class="actions mb">${btn('＋ Add a task','task-open','','btn primary')}${btn('Optional calendar file','calendar-export')}</div><div class="results-list">${tasks.map(t=>`<div class="list-card"><div class="row between"><div><h4>${safe(t.name)}</h4><p>${safe(timeLabel(t.time))} · ${Array.isArray(t.days)?t.days.map(d=>SHORT[d]).join(', '):'Daily'} · ${safe(t.category||'Routine')}</p></div><div class="actions">${btn('Edit','task-open',`data-id="${safe(t.id)}"`)}${btn('Delete','task-delete',`data-id="${safe(t.id)}"`)}</div></div></div>`).join('')||'<p class="muted-line">No routine configured. Import your private setup or add tasks.</p>'}</div>`)}${section('Connections and limitations',`<p class="muted-line">Apple Health and external delivery services are <strong>not connected</strong>. iPhone background push notifications are <strong>not provided</strong> by this static site. A local timer cannot guarantee reminders while the app is closed.</p><p class="muted-line">For reliable reminders, use Apple Reminders manually or review the optional calendar file before importing it. It could duplicate existing reminders.</p>`)}${section('Data exports',`<div class="actions">${btn('Meal CSV','export-meals')}${btn('Symptom CSV','episode-export')}${btn('Measurement CSV','export-metrics')}</div>`)} `}
function onboarding(){return `<div class="shell"><main class="main" style="max-width:720px;padding-top:35px"><div class="brand"><div class="brand-mark">✳</div><div class="brand-text">My Wellness<br>Companion</div></div><div class="hero" style="margin-top:27px"><div class="hero-copy"><div class="small-label">YOUR APP, YOUR DATA</div><h2>A quieter way to look after yourself.</h2><p>Your personal routine can be imported privately after opening the app. It isn't embedded in the public website.</p></div></div>${section('Get started',`<div class="actions">${btn('Import my private setup','import','','btn primary')}${btn('Start with a blank app','start-blank')}</div><div class="privacy-box mt">Your personal configuration and logs are saved locally on this device—not uploaded to GitHub. Protect your device and download backups regularly.</div><p class="card-caption mt">If you have a private setup JSON, save it to your iPhone Files app, then tap Import. You can also customise tasks yourself.</p>`)}</main></div>${modal||''}`}
function bootRender(){if(!initialized)return;if(!data.extra?.ready)$('app').innerHTML=onboarding();else render()}
function popup(title,html){modal=`<div class="modal-wrap" role="presentation"><div class="modal" role="dialog" aria-modal="true" aria-label="${safe(title)}"><button class="icon-btn close" data-action="close" aria-label="Close">×</button><h2>${safe(title)}</h2><div class="modal-body">${html}</div></div></div>`;bootRender()}
function close(){modal=null;bootRender()}
function formModal(title,formId,body,label='Save'){popup(title,`<form id="${safe(formId)}" class="form-row">${body}<div class="modal-footer">${btn('Cancel','close')}<button class="btn primary" type="submit">${safe(label)}</button></div></form>`)}
function editMeal(item=null,suggestion={}){const date=item?.date||selected;formModal(item?'Edit actual meal':'Record what you ate','mealEdit',`<input type="hidden" name="id" value="${safe(item?.id||'')}">${field('Date','date','date',date,'required')}${dropdown('Meal','type',['Breakfast','Lunch','Dinner','Snack'],item?.type||suggestion.type||'Breakfast')}${field('Food actually eaten','name','text',item?.name||suggestion.name||'','required maxlength="160"')}${field('Time','time','time',item?.time||'')}${field('Portion / quantity (optional)','portion','text',item?.portion||'')}${dropdown('Source','source',['Homemade','Ordered','Eating out','Other'],item?.source||'Homemade')}${textarea('Notes (optional)','notes',item?.notes||'')}`)}
function editTask(item=null){const t=item||{name:'',time:'',group:'Morning',category:'routine',days:[0,1,2,3,4,5,6],notes:'',active:true};formModal(item?'Edit recurring task':'Add recurring task','taskEdit',`<input type="hidden" name="id" value="${safe(t.id||'')}">${field('Task name','name','text',t.name,'required maxlength="160"')}${field('Time (optional)','time','time',t.time)}${dropdown('Part of day','group',['Morning','Afternoon','Evening','Night','Other'],t.group||'Morning')}${dropdown('Type of task','category',[['routine','Routine'],['medication','Medicine'],['supplement','Supplement'],['fitness','Fitness'],['care','Care'],['appointment','Class / appointment']],t.category||'routine')}${textarea('Notes / instructions','notes',t.notes||'')}<div class="label-line">Repeats on</div><div class="chips">${SHORT.map((day,i)=>`<label class="day-toggle"><input type="checkbox" name="dow" value="${i}" ${(t.days||[]).includes(i)?'checked':''}> ${day}</label>`).join('')}</div><p class="card-caption">Medicine logs require explicit confirmation. Leave a time empty until it is known.</p>`)}
function editProfile(){const p=data.profile;formModal('Your private profile','profileEdit',`${field('Name / greeting','name','text',p.name)}${field('Starting weight (optional)','weightStart','number',p.weightStart,'step="0.1"')}${field('First weight goal (optional)','weightGoal','number',p.weightGoal,'step="0.1"')}${field('Longer-term weight goal (optional)','weightLong','number',p.weightLong,'step="0.1"')}${field('Meditation duration (minutes)','meditationMinutes','number',p.meditationMinutes,'min="1" max="180"')}${textarea('Private personal notes','notes',p.notes||'')}`)}
function editCheckin(period){let x=data.checkins.find(x=>x.date===selected&&x.period===period);formModal(period==='morning'?'Morning check-in':'Evening check-in','checkinEdit',`<input type="hidden" name="date" value="${selected}"><input type="hidden" name="period" value="${period}">${['energy','sleep','mood','stress'].map(k=>dropdown(k[0].toUpperCase()+k.slice(1)+' (1 low – 5 high)',k,Array.from({length:5},(_,i)=>[i+1,String(i+1)]),x?.[k]||'3')).join('')}${textarea('Symptoms / recovery / reflections (optional)','notes',x?.notes||'')}`)}
const METRIC_UNITS={'Weight':'kg','Blood pressure — systolic':'mmHg','Blood pressure — diastolic':'mmHg','Steps':'steps','Active calories':'kcal','Exercise minutes':'min','Sleep hours':'hours','Ferritin':'ng/mL','Vitamin D':'ng/mL'};
function metricUnit(kind,unit){return unit||METRIC_UNITS[kind]||''}
function editMetric(kind='Weight'){const units=['kg','lb','cm','mm','mmHg','steps','kcal','min','hours','ng/mL','µg/L','nmol/L','other'];const unit=metricUnit(kind);formModal('Record a measurement','metricEdit',`${field('Date','date','date',selected,'required')}${dropdown('Metric','kind',[...new Set(['Weight','Blood pressure — systolic','Blood pressure — diastolic','Steps','Active calories','Exercise minutes','Sleep hours','Ferritin','Vitamin D',...(data.config.healthMetrics||[])])],kind)}${field('Value','value','number','','required step="any"')}${dropdown('Unit','unit',units.map(x=>[x,x]),unit||'other')}${field('Time (optional)','time','time','')}<p class="card-caption">Check the unit before saving, especially for laboratory results.</p>`)}
function editSession(date=selected,name=''){formModal('Log exercise or badminton','sessionEdit',`${field('Date','date','date',date,'required')}${field('Activity','name','text',name||workout(date)||'','required maxlength="160"')}${field('Duration (minutes)','duration','number','45','min="0" max="1440"')}${textarea('Exercises, weights, effort or recovery','notes','')}`)}
function swapModal(source){const w=workout(source),wk=monday(source);formModal('Swap gym days','swapEdit',`<p class="muted-line"><strong>${WEEK[dow(source)]}: ${safe(w||'Rest day')}</strong>. Choose the other weekday. Only this week will change.</p><input type="hidden" name="source" value="${source}"><label class="field">Swap with<select name="target">${Array.from({length:7},(_,i)=>plus(wk,i)).filter(d=>d!==source).map(d=>`<option value="${d}">${WEEK[dow(d)]} — ${safe(workout(d)||'Rest day')}</option>`).join('')}</select></label>`,'Swap gym days')}
function editEpisode(ep=null){const start=ep?.start||new Date().toISOString(),local=s=>{let d=new Date(s);let parts=new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Kolkata',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(d);return parts.replace(' ','T')};formModal(ep?'Edit symptom episode':'Record symptom episode','episodeEdit',`<input type="hidden" name="id" value="${safe(ep?.id||'')}">${field('Start time (IST)','start','datetime-local',local(start),'required')}${field('End time (IST, optional)','end','datetime-local',ep?.end?local(ep.end):'')}${dropdown('Severity','severity',[['','Not recorded'],['mild','Mild'],['moderate','Moderate'],['severe','Severe']],ep?.severity||'')}${textarea('Symptoms observed','symptoms',ep?.symptoms||'',data.config.symptomFields?.join(', ')||'')}${textarea('Possible triggers (optional)','triggers',ep?.triggers||'')}${textarea('Notes / recovery','notes',ep?.notes||'')}<div class="banner-alert">New, unusual, sudden or persistent stroke-like symptoms require emergency medical assessment. The app cannot diagnose an episode.</div>`)}
function endEpisode(){const item=data.episodes.find(e=>!e.end);if(!item){toast('No active episode');return}item.end=new Date().toISOString();save();render();toast('Episode end saved')}
function logMeditation(){const minutes=Math.max(1,Number(data.profile.meditationMinutes)||15);data.meditations.push({id:uid(),date:isoDay(),minutes});const meditationTask=taskList(isoDay()).find(t=>/meditat/i.test(t.name));if(meditationTask)day(isoDay()).tasks[meditationTask.id]='done';medTimer=null;save();render();toast('Meditation logged')}
function icsEscape(s){return String(s||'').replaceAll('\\','\\\\').replaceAll(';','\\;').replaceAll(',','\\,').replaceAll('\n','\\n')}
function calendarExport(){let events=[];const start=isoDay(),dateAtDay=d=>{let p=plus(start,(d-dow(start)+7)%7);return p.replaceAll('-','')};for(const task of data.config.tasks){if(!task.time||task.active===false)continue;const days=Array.isArray(task.days)?task.days:[0,1,2,3,4,5,6];if(!days.length)continue;for(const d of days){let startDate=dateAtDay(d),label=icsEscape(task.name),hhmm=task.time.replace(':','');let minutes=Number(task.time.slice(0,2))*60+Number(task.time.slice(3))+5;let endHH=String(Math.floor(minutes/60)%24).padStart(2,'0')+String(minutes%60).padStart(2,'0');events.push(['BEGIN:VEVENT','UID:'+uid()+'@companion.invalid','DTSTAMP:'+new Date().toISOString().replace(/[-:]|\.\d{3}/g,'').replace('.000',''),'DTSTART;TZID=Asia/Kolkata:'+startDate+'T'+hhmm+'00','DTEND;TZID=Asia/Kolkata:'+startDate+'T'+endHH+'00','RRULE:FREQ=WEEKLY','SUMMARY:'+label,'END:VEVENT'].join('\r\n'));}}
saveFile('companion-optional-calendar.ics',['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Companion//Export//EN','CALSCALE:GREGORIAN',...events,'END:VCALENDAR'].join('\r\n'),'text/calendar');toast('Optional calendar file exported. Review for duplicates.')}
function swap(source,target){if(source===target)throw Error('Choose different dates');let a=workout(source),b=workout(target);data.workoutOverrides[source]=b;data.workoutOverrides[target]=a;save();close();render();toast('Workouts swapped for the selected dates')}
function chatMessage(role,message){data.chat.push({id:uid(),role,text:message,at:new Date().toISOString()});if(data.chat.length>160)data.chat=data.chat.slice(-160)}
function answer(q){const text=q.trim(),low=text.toLowerCase(),today=isoDay();if(!text)return;chatMessage('user',text);let response='',action=null;
if(/(sudden|stroke|new weakness|slurred speech|vision loss|can't speak|cannot speak)/i.test(low)){response='New, sudden, unusual or persistent weakness, speech or vision changes can be emergencies. Seek emergency medical assessment. This app cannot determine their cause.'}
else if(/(swap|move|exchange).*(workout|gym|monday|tuesday|wednesday|thursday|friday|saturday|sunday)|(gym|workout).*(swap|move)/i.test(low)){const matches=[...low.matchAll(/monday|tuesday|wednesday|thursday|friday|saturday|sunday/g)].map(m=>m[0]);if(matches.length<2)response='Tell me two weekdays, e.g. “Swap Monday and Thursday workouts”.';else{const wk=monday(today),from=plus(wk,(WEEK.findIndex(d=>d.toLowerCase()===matches[0])+6)%7),to=plus(wk,(WEEK.findIndex(d=>d.toLowerCase()===matches[1])+6)%7);action={type:'swap',from,to};response=`Swap ${dateLabel(from)} (${workout(from)||'Rest'}) with ${dateLabel(to)} (${workout(to)||'Rest'})? I will only change these dates.`}}
else if(/^(i ate|i had|log|record)\b/i.test(low)&&/(breakfast|lunch|dinner|snack)/i.test(low)){let meal=['Breakfast','Lunch','Dinner','Snack'].find(x=>low.includes(x.toLowerCase()))||'Snack',food=text.replace(/^(i ate|i had|log|record)\s*/i,'').replace(/\s*(for|at)\s+(breakfast|lunch|dinner|snack).*$/i,'').trim();if(!food||/^(breakfast|lunch|dinner|snack)$/i.test(food))response='Tell me which food you ate, such as “I had oats for breakfast”.';else{action={type:'meal',name:food,meal,date:today};response=`Record “${food}” as your actual ${meal.toLowerCase()} today?`}}
else if(/(show|did i|have i|record|taken|medication|medicine|supplement).*(medicine|medication|dose|supplement|taken)|(what).*medicines/i.test(low)){let meds=taskList(today).filter(x=>['medication','supplement'].includes(x.category));response=meds.length?'Today’s recorded medicine/supplement status:\n'+meds.map(t=>`• ${t.name}: ${getTask(today,t.id)==='done'?'logged as taken':getTask(today,t.id)==='skipped'?'logged as skipped':'not recorded'}`).join('\n')+'\nA blank log does not prove a dose was missed.':'You have no medicines or supplements configured for today.'}
else if(/(what|show|left|next|today|tasks|schedule|checklist)/i.test(low)&&!/(meal|food|ate|eaten|breakfast|lunch|dinner)/i.test(low)){let tasks=taskList(today),todo=tasks.filter(t=>getTask(today,t.id)!=='done');response=`${completion(today).done} of ${tasks.length} scheduled items recorded complete.\n${todo.slice(0,12).map(t=>'• '+timeLabel(t.time)+' — '+t.name).join('\n')||'All recorded complete!'}${todo.length>12?'\n…and more.':''}`}
else if(/(what|show|log).*(ate|meals|food|eaten)/i.test(low)){let date=/yesterday/i.test(low)?plus(today,-1):today,items=data.meals.filter(m=>m.date===date);response=items.length?`Actual meal entries for ${dateLabel(date)}:\n`+items.map(m=>'• '+m.type+': '+m.name).join('\n'):'No meals logged for that date. This does not mean you skipped eating.'}
else if(/(eat|food|meal|breakfast|lunch|dinner|snack|suggest|order)/i.test(low)){let type=['Breakfast','Lunch','Dinner','Snack'].find(t=>low.includes(t.toLowerCase()))||'Breakfast';let foods=data.config.mealIdeas[type]||[];response=foods.length?`Possible ${type.toLowerCase()} choices:\n`+foods.slice(0,5).map(x=>'• '+(typeof x==='string'?x:x.name)).join('\n')+'\nThese suggestions are not diary entries.':'There are no suggestions imported for that meal yet. You can still log what you ate in Food.'}
else if(/(symptom|episode|health|trigger)/i.test(low)){response=`You have ${data.episodes.length} symptom episodes recorded. Use Health → Symptoms for the timeline and export. Patterns are not diagnoses.`}
else if(/(care|skin|hair|serum|sunscreen|products)/i.test(low)){let routine=data.config.care[/night|evening/i.test(low)?'night':'morning']||[];response=routine.length?'Your configured routine:\n'+routine.map(x=>'• '+x.name).join('\n'):'Your care routine is empty. Import it from your private setup or add entries.'}
else if(/(meditat|sleep|rest|tired|fatigue)/i.test(low)){response=`You can start ${Number(data.profile.meditationMinutes)||15} minutes of meditation from Health → Meditation. Rest and recovery count. If persistent fatigue is limiting your life, discuss it with your clinician.`}
else if(/(progress|weight|motivat|encourag|goal)/i.test(low)){response=QUOTES[Math.floor(Date.now()/86400000)%QUOTES.length]+`\nRecorded workouts: ${data.workouts.length}; check-ins: ${data.checkins.length}. Your progress isn't measured by a single day.`}
else response='I can check today’s tasks and recorded medicines, suggest meals from your private setup, show food logs, prepare a workout swap, show your care routine, or explain your recorded wellness trends. I am an offline local assistant, not a generative medical chatbot.';
chatMessage('assistant',response);pending=action;save();render()}
function confirmAction(){if(!pending)return;let act=pending;pending=null;if(act.type==='swap'){swap(act.from,act.to);chatMessage('assistant','Workout swap saved successfully.')}else if(act.type==='meal'){data.meals.push({id:uid(),date:act.date,type:act.meal,name:act.name,time:'',portion:'',source:'Other',notes:''});save();chatMessage('assistant','Meal saved in your actual food diary.')}save();render()}
function exportEpisodes(){csv('companion-symptom-episodes-'+isoDay()+'.csv',['Start IST','End IST','Severity','Symptoms','Possible triggers','Notes'],data.episodes.map(e=>[fmtDateTime(e.start),fmtDateTime(e.end),e.severity,e.symptoms,e.triggers,e.notes]));toast('Symptom report downloaded')}
function deletePrompt(type,id){if(!['meals','workouts','episodes','metrics'].includes(type))return;const item=data[type].find(x=>x.id===id);if(!item)return;popup('Delete this entry?',`<p class="muted-line">This deletes the entry from local storage. You can keep a backup first.</p><div class="actions">${btn('Cancel','close')}${btn('Delete permanently','delete-confirm',`data-type="${type}" data-id="${safe(id)}"`,'btn danger')}</div>`)}
function resetPrompt(){popup('Erase your personal data?',`<div class="banner-alert">This erases your imported profile, routines, wellness logs and chat from this device. It cannot be undone. Please download a backup first.</div><div class="actions">${btn('Cancel','close')}${btn('Erase everything','reset-confirm','','btn danger')}</div>`)}
function calendarPrompt(){popup('Calendar export is optional',`<div class="notice warning">You might already have reminders in another calendar. Importing these events could create duplicates. This feature downloads a file; it does not change any calendar by itself.</div><div class="actions">${btn('Cancel','close')}${btn('Download calendar file','calendar-confirm','','btn primary')}</div>`)}
function taskMenu(id,date){let t=taskList(date).find(x=>x.id===id);if(!t)return;popup(t.name,`<div class="card-caption">${safe(t.notes||'')} · ${timeLabel(t.time)}</div><div class="actions">${btn('Done','task-set',`data-id="${safe(id)}" data-day="${date}" data-status="done"`)}${btn('Skip','task-set',`data-id="${safe(id)}" data-day="${date}" data-status="skipped"`)}${btn('Clear status','task-set',`data-id="${safe(id)}" data-day="${date}" data-status=""`)}</div>`)}
function handleClick(ev){const el=ev.target.closest('[data-action]');if(!el)return;const act=el.dataset.action;try{switch(act){case 'tab':tab=el.dataset.value;close();window.scrollTo(0,0);break;case 'date-shift':selected=plus(selected,Number(el.dataset.dir));render();break;case 'fitness-week':fitnessWeekShift=el.dataset.shift==='0'?0:fitnessWeekShift+Number(el.dataset.shift);render();break;case 'checkin-period':homeCheckPeriod=el.dataset.value;render();break;case 'meal-idea':{const form=$('mealQuick-'+el.dataset.meal);if(form){const input=form.querySelector('input[name=name]');input.value=el.dataset.name;input.focus();input.scrollIntoView({block:'center',behavior:'smooth'});}break;}case 'task-toggle':{let v=getTask(el.dataset.day,el.dataset.id);setStatus(el.dataset.day,el.dataset.id,v==='done'?'':'done');break}case 'task-menu':taskMenu(el.dataset.id,el.dataset.day);break;case 'task-set':{let {day:date,id,status}=el.dataset;close();setStatus(date,id,status);break}case 'close':close();break;case 'start-blank':data.extra.ready=true;save();bootRender();break;case 'import':$('importFile').click();break;case 'backup':backup();break;case 'profile-open':editProfile();break;case 'task-open':editTask(data.config.tasks.find(t=>t.id===el.dataset.id));break;case 'task-delete':{if(!confirm('Delete this recurring task from the routine? Historical entries will remain in backups.'))return;data.config.tasks=data.config.tasks.filter(t=>t.id!==el.dataset.id);save();render();break}case 'meal-open':editMeal(data.meals.find(m=>m.id===el.dataset.id),{type:el.dataset.type,name:el.dataset.name});break;case 'delivery-link':toast('No external delivery account is connected. Open the delivery app separately.');break;case 'water':day(selected).water=Math.max(0,(day(selected).water||0)+Number(el.dataset.inc));save();render();break;case 'care-check':{let id='care-'+el.dataset.period+'-'+el.dataset.index;day(selected).tasks[id]=getTask(selected,id)==='done'?'':'done';save();render();break}case 'health-sub':healthView=el.dataset.value;render();break;case 'care-sub':carePeriod=el.dataset.value;render();break;case 'checkin-open':editCheckin(el.dataset.period||'morning');break;case 'metric-open':editMetric(el.dataset.kind||'Weight');break;case 'session-open':editSession(el.dataset.date||selected,el.dataset.name||'');break;case 'swap-open':swapModal(el.dataset.date||selected);break;case 'week-reset':{let wk=plus(monday(isoDay()),fitnessWeekShift*7);if(!confirm('Restore the default workout plan for this week?'))return;for(let i=0;i<7;i++)delete data.workoutOverrides[plus(wk,i)];save();render();break}case 'episode-open':editEpisode(data.episodes.find(x=>x.id===el.dataset.id));break;case 'episode-start':{if(data.episodes.some(x=>!x.end)){healthView='symptoms';render();toast('Episode already in progress');return}data.episodes.push({id:uid(),start:new Date().toISOString(),end:'',severity:'',symptoms:'',triggers:'',notes:''});save();render();toast('Episode start recorded');break}case 'episode-end':endEpisode();break;case 'episode-export':exportEpisodes();break;case 'meditation-start':medTimer={finish:Date.now()+(Math.max(1,Number(data.profile.meditationMinutes)||15)*60*1000)};render();break;case 'meditation-stop':medTimer=null;render();break;case 'meditation-log':logMeditation();break;case 'theme-toggle':localStorage.setItem('companion-theme',localStorage.getItem('companion-theme')==='dark'?'light':'dark');render();break;case 'delete':deletePrompt(el.dataset.type,el.dataset.id);break;case 'delete-confirm':{let type=el.dataset.type,old=data[type].find(x=>x.id===el.dataset.id);data[type]=data[type].filter(x=>x.id!==el.dataset.id);if(type==='meals'&&old)syncMealChecklist(old.date,old.type);save();close();render();break}case 'reset-open':resetPrompt();break;case 'reset-confirm':data=EMPTY();save();close();bootRender();toast('All records cleared');break;case 'export-meals':csv('companion-meals-'+isoDay()+'.csv',['Date','Meal','Food','Time','Portion','Source','Notes'],data.meals.map(m=>[m.date,m.type,m.name,m.time,m.portion,m.source,m.notes]));break;case 'export-metrics':csv('companion-measurements-'+isoDay()+'.csv',['Date','Metric','Value','Unit','Time'],data.metrics.map(m=>[m.date,m.kind,m.value,metricUnit(m.kind,m.unit),m.time]));break;case 'calendar-export':calendarPrompt();break;case 'calendar-confirm':calendarExport();close();break;case 'chat-prompt':answer(el.dataset.text);break;case 'chat-confirm':confirmAction();break;case 'chat-cancel':pending=null;chatMessage('assistant','Cancelled. No changes made.');save();render();break;case 'chat-clear':{if(!confirm('Clear all locally saved chat messages?'))return;data.chat=[];pending=null;save();render();break}default:break}}catch(e){console.error(e);toast('Could not complete action: '+e.message)}}
function isoLocal(input){if(!input)return '';return new Date(input+':00+05:30').toISOString()}
function handleSubmit(ev){const f=ev.target;if(!f.id||(!['mealEdit','taskEdit','profileEdit','checkinEdit','quickCheckin','metricEdit','sessionEdit','swapEdit','episodeEdit','chatForm'].includes(f.id)&&!f.id.startsWith('mealQuick-')))return;ev.preventDefault();let v=Object.fromEntries(new FormData(f).entries());try{if(f.id.startsWith('mealQuick-')){if(!String(v.name||'').trim())throw Error('Enter what you actually ate');data.meals.push({id:uid(),date:v.date,type:v.type,name:String(v.name).trim(),time:v.time||'',portion:v.portion||'',source:'Other',notes:''});syncMealChecklist(v.date,v.type);save();render();toast('Actual meal saved');return;}switch(f.id){case 'quickCheckin':{const item={id:uid(),date:v.date,period:v.period,energy:v.energy,sleep:v.sleep,mood:v.mood,stress:v.stress,notes:v.notes||''};data.checkins=data.checkins.filter(x=>x.date!==item.date||x.period!==item.period);data.checkins.push(item);save();render();toast('Wellness check-in saved');return;}case 'mealEdit':{const item={id:v.id||uid(),date:v.date,type:v.type,name:v.name.trim(),time:v.time,portion:v.portion,source:v.source,notes:v.notes};if(!item.name)throw Error('Food is required');data.meals=data.meals.filter(m=>m.id!==item.id);data.meals.push(item);syncMealChecklist(item.date,item.type);break}case 'taskEdit':{let weekdays=[...f.querySelectorAll('input[name="dow"]:checked')].map(x=>Number(x.value));if(!weekdays.length)throw Error('Choose at least one day');const item={id:v.id||uid(),name:v.name.trim(),time:v.time,group:v.group,category:v.category,notes:v.notes,days:weekdays,active:true};if(!item.name)throw Error('Task name is required');data.config.tasks=data.config.tasks.filter(x=>x.id!==item.id);data.config.tasks.push(item);break}case 'profileEdit':data.profile={...data.profile,name:v.name,weightStart:v.weightStart,weightGoal:v.weightGoal,weightLong:v.weightLong,meditationMinutes:Math.max(1,Number(v.meditationMinutes)||15),notes:v.notes};break;case 'checkinEdit':{let item={id:uid(),date:v.date,period:v.period,energy:v.energy,sleep:v.sleep,mood:v.mood,stress:v.stress,notes:v.notes};data.checkins=data.checkins.filter(x=>x.date!==item.date||x.period!==item.period);data.checkins.push(item);break}case 'metricEdit':{let value=n(v.value);if(value===null)throw Error('Enter a valid number');data.metrics.push({id:uid(),kind:v.kind,value,unit:v.unit,date:v.date,time:v.time});break}case 'sessionEdit':{data.workouts.push({id:uid(),date:v.date,name:v.name,duration:v.duration,notes:v.notes});if(/badminton/i.test(v.name)){const b=badmintonTask(v.date);if(b)day(v.date).tasks[b.id]='done';}else if(v.name.trim()===workout(v.date))day(v.date).tasks['workout-of-day']='done';break;}case 'swapEdit':swap(v.source,v.target);return;case 'episodeEdit':{let start=isoLocal(v.start),end=isoLocal(v.end);if(end&&new Date(end)<new Date(start))throw Error('End cannot be before start');let item={id:v.id||uid(),start,end,severity:v.severity,symptoms:v.symptoms,triggers:v.triggers,notes:v.notes};data.episodes=data.episodes.filter(x=>x.id!==item.id);data.episodes.push(item);break}case 'chatForm':{chatDraft='';answer(v.message);return}}save();close();toast('Saved to your device')}catch(e){console.error(e);toast(e.message||'Unable to save')}}
async function importFile(ev){let f=ev.target.files?.[0];if(!f)return;try{if(f.size>15000000)throw Error('File exceeds 15 MB');let payload=JSON.parse(await f.text());let incoming=normalise(payload);if(data.extra.ready&&!confirm('This replaces your local app data and routines. Download a backup first. Continue?'))return;data=incoming;data.extra={...data.extra,ready:true};pending=null;selected=isoDay();save();modal=null;bootRender();toast('Private setup imported on this device')}catch(e){toast('Could not import: '+e.message)}finally{ev.target.value=''}}
async function boot(){selected=isoDay();try{db=await openDb();let current=await loadDb();if(current&&current.schema===VER)data=current;}catch(e){console.warn('IndexedDB unavailable',e);storageWarning='Database storage unavailable. Browser storage is being used; make backups regularly.';try{const current=localStorage.getItem('wellness-companion-generic-v4');if(current)data=JSON.parse(current)}catch{}}initialized=true;bootRender();if('serviceWorker'in navigator){navigator.serviceWorker.register('./sw.js').catch(e=>console.warn('Offline support unavailable',e))}}
document.addEventListener('click',handleClick);
document.addEventListener('submit',handleSubmit);
document.addEventListener('change',event=>{if(event.target.id==='daySelect'){selected=event.target.value;render()}if(event.target.id==='importFile')importFile(event);if(event.target.name==='kind'&&event.target.closest('#metricEdit')){const u=event.target.closest('form').querySelector('select[name=unit]');if(u){const unit=metricUnit(event.target.value);if(unit&&[...u.options].some(o=>o.value===unit))u.value=unit;}}});
document.addEventListener('input',event=>{if(event.target.closest('#chatForm')&&event.target.name==='message')chatDraft=event.target.value});
setInterval(()=>{if(medTimer){let left=Math.max(0,(medTimer.finish-Date.now())/1000),el=$('meditationClock');if(el)el.textContent=clock(left);if(left<=0){medTimer=null;toast('Meditation time complete — tap Mark completed to log')}}},1000);
boot();
})();
